namespace App\Http\Controllers\Fintech;

use App\Http\Controllers\Controller;
use App\Models\Wallet;
use App\Services\VirtualCardService;
use Illuminate\Http\Request;
use Illuminate\Http\JsonResponse;

class VirtualCardController extends Controller
{
    public function issue(Request $request, VirtualCardService $cardService): JsonResponse
    {
        if (!$request->user()->tokenCan('cards:create')) {
            abort(403, 'Unauthorized token ability.');
        }

        $wallet = $request->user()->wallets()->findOrFail($request->input('wallet_id'));
        $this->authorize('createCard', $wallet);

        $card = $cardService->createVirtualCard($wallet, $request->input('spending_limit'));

        return response()->json(['card' => $card], 201);
    }
}
